        .header-actions {
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .search-bar {
            background: white;
            border: 1px solid #e5e5e5;
            border-radius: 99px;
            padding: 8px 16px;
            display: flex;
            align-items: center;
            gap: 8px;
            width: 260px;
            color: #888;
            font-size: 13px;
        }

        .user-profile {
            display: flex;
            align-items: center;
            gap: 8px;
